-- Live targets reference the nullable UNIQUE delivery key; historical identities
-- carry no invented delivery, fingerprint, or message TTL. Shared by startup
-- and the explicit offline migration, which must not create runtime objects.
CREATE TABLE IF NOT EXISTS ordinary_messages(delivery_id TEXT COLLATE "C" UNIQUE,message_id TEXT COLLATE "C" NOT NULL UNIQUE,op_id TEXT COLLATE "C" NOT NULL UNIQUE,channel_id TEXT COLLATE "C" NOT NULL,fingerprint TEXT COLLATE "C",payload_blob BYTEA NOT NULL,payload_bytes BIGINT NOT NULL,accepted_at BIGINT NOT NULL,expires_at BIGINT,dedupe_until BIGINT NOT NULL,status TEXT COLLATE "C" NOT NULL,updated_at BIGINT NOT NULL,pending_targets BIGINT NOT NULL DEFAULT 0,provider_accepted_count BIGINT NOT NULL DEFAULT 0,provider_failed_count BIGINT NOT NULL DEFAULT 0,provider_target_count BIGINT NOT NULL DEFAULT 0,private_enqueued_count BIGINT NOT NULL DEFAULT 0,private_rejected_count BIGINT NOT NULL DEFAULT 0,thing_id TEXT COLLATE "C",identity_state TEXT COLLATE "C" NOT NULL DEFAULT 'live',CHECK((identity_state='live' AND delivery_id IS NOT NULL AND fingerprint IS NOT NULL AND expires_at IS NOT NULL) OR (identity_state='legacy_unverifiable' AND delivery_id IS NULL AND fingerprint IS NULL AND expires_at IS NULL AND payload_bytes=0 AND octet_length(payload_blob)=0 AND status='historical_unverifiable' AND pending_targets=0 AND provider_target_count=0 AND private_enqueued_count=0 AND provider_accepted_count=0 AND provider_failed_count=0 AND private_rejected_count=0)));
CREATE UNIQUE INDEX IF NOT EXISTS ordinary_historical_op ON ordinary_messages(lower(op_id)) WHERE identity_state='legacy_unverifiable';
